/* generic sheet form: fields=[key,label,type] */
function form(title,fields,init,onSave,extra=''){const b=sheet(`<h2 class="sh-h">${esc(title)}</h2>`+fields.map(([k,l,t])=>`<div class="fl"><label>${l}</label><input name="${k}" type="${t}" ${t==='number'?'step="any" inputmode="decimal" min="0"':''} ${t==='date'||t==='number'||t==='tel'?'dir="ltr"':''} value="${esc(init[k]??'')}"></div>`).join('')+`<div class="bar"><button class="btn p" data-ok>${SV(LU.check)}${L('حفظ')}</button>${extra}<button class="btn ghost" data-no>${L('إلغاء')}</button></div>`);
b.querySelector('[data-no]').onclick=()=>closeEl(b);b.querySelector('[data-ok]').onclick=async function(){if(this.disabled)return;this.disabled=true;const o={};for(const[k,,t]of fields){const el=b.querySelector(`[name="${k}"]`);o[k]=t==='number'?(el.value===''?0:+el.value):el.value.trim()}if(await onSave(o,b)!==false){closeEl(b);buzz()}else this.disabled=false};return b}
function stockForm(p){form(L('إضافة كمية — {n}',{n:p.name}),[['qty',L('الكمية المضافة'),'number'],['cost',L('سعر شراء القطعة في هذه الدفعة ($)'),'number']],{qty:1,cost:p.cost},async o=>{if(!(o.qty>0)||o.qty!==Math.floor(o.qty)){warn(L('أدخل كمية صحيحة'));return false}if(o.cost<0){warn(L('القيم لا يمكن أن تكون سالبة'));return false}
const old=p.qty*uc(p),nw=o.qty*(o.cost+(+p.ship||0)+(+p.extra||0));p.cost=num((old+nw)/(p.qty+o.qty)-(+p.ship||0)-(+p.extra||0));p.qty+=o.qty;p.updated=Date.now();await put('p',p);log('إضافة مخزون '+o.qty+' إلى '+p.name);ok(L('تمت إضافة الكمية ✓ (متوسط مرجّح للتكلفة)'));refresh()})}
function quickEdit(p){const b=form(L('تعديل سريع — {n}',{n:p.name}),[['price',L('سعر البيع ($)'),'number'],['qty',L('الكمية المتوفرة'),'number'],['min',L('حد التنبيه'),'number']],p,async o=>{if(!(o.price>0)){warn(L('أدخل سعر البيع'));return false}if(o.qty<0||o.min<0){warn(L('القيم لا يمكن أن تكون سالبة'));return false}p.price=o.price;p.qty=Math.max(0,Math.floor(o.qty));p.min=o.min;p.updated=Date.now();await put('p',p);log('تعديل سريع: '+p.name);ok(L('تم الحفظ ✓'));refresh()},`<button class="btn" data-fe>${L('تعديل كامل')}</button>`);b.querySelector('[data-fe]').onclick=()=>{closeEl(b);editProduct(p)}}

