P.d.querySelector('#cc').innerHTML=K(L('التكلفة الكاملة'),f(full))+K(L('صافي ربح القطعة'),f(pf),cl)+K(L('نسبة الربح على التكلفة'),num(pc)+'%',cl)+K(L('هامش الربح'),num(mg)+'%',cl)+K(L('ربح كامل المخزون'),f(pf*v('qty')),cl)+(pf<0&&v('price')?`<div class="note r">${SV(LU.warn)}${L('سعر البيع أقل من التكلفة')}</div>`:'');
